import extension from "../extension.js";
export function assertWriteChannel(ctx) {
    const { channels, refuseSession } = extension.config;
    if (channels !== undefined && !channels.includes(ctx.session.channelId)) {
        throw new Error(`Cloud agents cannot be launched or steered from the "${ctx.session.channelId}" channel.`);
    }
    const refusal = refuseSession?.(ctx.session);
    if (refusal !== undefined) {
        throw new Error(refusal);
    }
}
